import { createHash, randomBytes, timingSafeEqual } from 'crypto';
import { HttpStatus, Injectable } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { JwtService } from '@nestjs/jwt';
import { InjectRepository } from '@nestjs/typeorm';
import bcrypt from 'bcryptjs';
import { IsNull, MoreThan, Not, Repository } from 'typeorm';
import { AccessClaims, CanonicalRole } from '@dzongjuk/contracts';
import { DomainException } from '@dzongjuk/common';
import { AuditService } from './audit.service';
import { LoginDto, RegisterDto, UpdateOwnProfileDto, UpdatePasswordDto } from './dtos';
import { LoginAttemptEntity, NdiLoginRequestEntity, RoleEntity, SessionEntity, UserEntity } from './entities';
import { NdiProviderService } from './ndi-provider.service';
import { validatePassportPhotoDataUrl } from './profile-photo';

interface RequestContext {
  requestId: string;
  ip?: string;
  userAgent?: string;
}

@Injectable()
export class AuthService {
  constructor(
    @InjectRepository(UserEntity) private readonly users: Repository<UserEntity>,
    @InjectRepository(RoleEntity) private readonly roles: Repository<RoleEntity>,
    @InjectRepository(SessionEntity) private readonly sessions: Repository<SessionEntity>,
    @InjectRepository(LoginAttemptEntity) private readonly attempts: Repository<LoginAttemptEntity>,
    @InjectRepository(NdiLoginRequestEntity) private readonly ndiLogins: Repository<NdiLoginRequestEntity>,
    private readonly jwt: JwtService,
    private readonly config: ConfigService,
    private readonly audit: AuditService,
    private readonly ndi: NdiProviderService,
  ) {}

  async register(dto: RegisterDto, context: RequestContext) {
    const chosenEmail = dto.email?.trim().toLowerCase();
    const duplicate = await this.users.findOne({
      where: chosenEmail ? [{ email: chosenEmail }, { cid: dto.cid }] : { cid: dto.cid },
    });
    if (duplicate) throw new DomainException('USER_DUPLICATE', 'An account already exists for this email or CID.', 409);
    const role = await this.roles.findOneByOrFail({ code: CanonicalRole.TestTaker, active: true });
    const user = await this.users.save(this.users.create({
      email: chosenEmail || `${dto.cid}@dsts.bt`, emailSet: Boolean(chosenEmail),
      cid: dto.cid, fullName: dto.fullName.trim(), userId: await this.allocateUserId(),
      passwordHash: dto.password ? await bcrypt.hash(dto.password, 12) : null,
      passwordSet: Boolean(dto.password), dateOfBirth: dto.dateOfBirth || null,
      gender: dto.gender || null, contactNumber: dto.contactNumber?.trim() || null,
      education: dto.education?.trim() || null, photo: null,
      roles: [role], status: 'ACTIVE',
    }));
    await this.audit.record({ action: 'USER_REGISTERED', resourceType: 'User', resourceId: user.id, actorUserId: user.id, requestId: context.requestId });
    return this.createSession(user, 'LOCAL', context);
  }

  async updateProfile(userId: string, dto: UpdateOwnProfileDto, context: RequestContext) {
    const user = await this.users.findOneBy({ id: userId });
    if (!user) throw new DomainException('USER_NOT_FOUND', 'User account not found.', 404);
    if (dto.email) {
      const email = dto.email.trim().toLowerCase();
      const duplicate = await this.users.findOne({ where: { email, id: Not(userId) } });
      if (duplicate) throw new DomainException('EMAIL_ALREADY_USED', 'This email address is already registered.', 409);
      user.email = email;
      user.emailSet = true;
    }
    if (dto.fullNameDz !== undefined) user.fullNameDz = dto.fullNameDz.trim() || null;
    const contactNumber = dto.contactNumber ?? dto.phone;
    if (contactNumber !== undefined) user.contactNumber = contactNumber.trim() || null;
    if (dto.education !== undefined) user.education = dto.education.trim() || null;
    const photo = dto.photo ?? dto.avatar;
    if (photo !== undefined) user.photo = await validatePassportPhotoDataUrl(photo);
    await this.users.save(user);
    await this.audit.record({
      action: 'PROFILE_UPDATED', resourceType: 'User', resourceId: user.id,
      actorUserId: user.id, requestId: context.requestId,
      safeData: { fields: Object.keys(dto).filter((field) => !['photo', 'avatar'].includes(field)), photoUpdated: photo !== undefined },
    });
    return this.publicUser(user);
  }

  async updatePassword(userId: string, dto: UpdatePasswordDto, context: RequestContext) {
    const user = await this.users.createQueryBuilder('user').addSelect('user.passwordHash')
      .leftJoinAndSelect('user.roles', 'role').leftJoinAndSelect('role.permissions', 'permission')
      .where('user.id = :userId', { userId }).getOne();
    if (!user) throw new DomainException('USER_NOT_FOUND', 'User account not found.', 404);
    if (user.passwordSet && (!dto.currentPassword || !user.passwordHash || !(await bcrypt.compare(dto.currentPassword, user.passwordHash)))) {
      throw new DomainException('CURRENT_PASSWORD_INVALID', 'The current password is incorrect.', 400);
    }
    user.passwordHash = await bcrypt.hash(dto.newPassword, 12);
    user.passwordSet = true;
    await this.users.save(user);
    await this.audit.record({ action: 'PASSWORD_UPDATED', resourceType: 'User', resourceId: user.id, actorUserId: user.id, requestId: context.requestId });
    return { passwordSet: true };
  }

  async updateAvatar(userId: string, photo: string, context: RequestContext) {
    return this.updateProfile(userId, { photo }, context);
  }

  /**
   * Allocates the next 4-digit login handle in sequence: one past the highest
   * currently in use (seed accounts start at 1001). The inner loop only advances if
   * a concurrent insert already claimed the computed number.
   */
  private async allocateUserId(): Promise<string> {
    const [highest] = await this.users.find({
      where: { userId: Not(IsNull()) }, select: ['id', 'userId'], order: { userId: 'DESC' }, take: 1,
    });
    let next = (Number(highest?.userId) || 1000) + 1;
    for (let attempt = 0; attempt < 25; attempt += 1, next += 1) {
      const candidate = String(next).padStart(4, '0');
      if (!(await this.users.findOne({ where: { userId: candidate } }))) return candidate;
    }
    throw new DomainException('USER_ID_ALLOCATION_FAILED', 'Could not allocate a unique User ID. Please try again.', 503);
  }

  async login(dto: LoginDto, context: RequestContext) {
    const identifier = dto.identifier.trim().toLowerCase();
    const user = await this.users.createQueryBuilder('user')
      .addSelect('user.passwordHash')
      .leftJoinAndSelect('user.roles', 'role')
      .leftJoinAndSelect('role.permissions', 'permission')
      .where('LOWER(user.email) = :identifier OR user.cid = :identifier OR user.userId = :identifier', { identifier })
      .getOne();
    if (!user) return this.failedLogin(identifier, null, context, 'INVALID_CREDENTIALS');
    if (user.status === 'DISABLED') throw new DomainException('ACCOUNT_DISABLED', 'This account is disabled.', 403);
    if (user.lockedUntil && user.lockedUntil > new Date()) throw new DomainException('ACCOUNT_LOCKED', 'This account is temporarily locked.', 423);
    if (user.status === 'LOCKED') user.status = 'ACTIVE';
    const allowAdministrativePasswordLogin = this.config.get<string>('ALLOW_ADMIN_LOCAL_LOGIN', 'false') === 'true';
    if (user.roles.some((role) => role.administrative) && !allowAdministrativePasswordLogin) {
      await this.logAttempt(identifier, false, context, 'ADMIN_NDI_REQUIRED');
      throw new DomainException('ADMIN_NDI_REQUIRED', 'Administrative users must authenticate using NDI.', 403);
    }
    if (!user.passwordHash || !(await bcrypt.compare(dto.password, user.passwordHash))) {
      return this.failedLogin(identifier, user, context, 'INVALID_CREDENTIALS');
    }
    user.failedLoginCount = 0;
    user.lockedUntil = null;
    await this.users.save(user);
    await this.logAttempt(identifier, true, context, null);
    return this.createSession(user, 'LOCAL', context);
  }

  async refresh(refreshToken: string | undefined, context: RequestContext) {
    if (!refreshToken) throw new DomainException('REFRESH_REQUIRED', 'A refresh token is required.', 401);
    const now = new Date();
    const session = await this.sessions.findOne({
      where: { refreshTokenHash: this.hash(refreshToken), revokedAt: IsNull(), expiresAt: MoreThan(now) },
    });
    if (!session) throw new DomainException('SESSION_INVALID', 'The session is invalid or expired.', 401);
    const idleMinutes = this.config.get<number>('SESSION_IDLE_MINUTES', 15);
    if (now.getTime() - session.lastActivityAt.getTime() >= idleMinutes * 60_000) {
      session.revokedAt = now;
      await this.sessions.save(session);
      throw new DomainException('SESSION_IDLE_TIMEOUT', 'The session expired due to inactivity.', 401);
    }
    const rawRefresh = randomBytes(48).toString('base64url');
    session.refreshTokenHash = this.hash(rawRefresh);
    session.lastActivityAt = now;
    // A reset may revoke the session after lookup. Never save a stale entity
    // with revokedAt=null over that revocation; rotate only a still-valid token.
    const rotation = await this.sessions.update({
      id: session.id, refreshTokenHash: this.hash(refreshToken), revokedAt: IsNull(), expiresAt: MoreThan(now),
    }, { refreshTokenHash: session.refreshTokenHash, lastActivityAt: now });
    if (rotation.affected !== 1) throw new DomainException('SESSION_INVALID', 'The session is invalid or expired.', 401);
    await this.audit.record({ action: 'SESSION_REFRESHED', resourceType: 'Session', resourceId: session.id, actorUserId: session.user.id, requestId: context.requestId });
    return { ...this.tokens(session), refreshToken: rawRefresh };
  }

  async logout(refreshToken: string | undefined, context: RequestContext) {
    if (!refreshToken) return;
    const session = await this.sessions.findOneBy({ refreshTokenHash: this.hash(refreshToken), revokedAt: IsNull() });
    if (!session) return;
    session.revokedAt = new Date();
    await this.sessions.save(session);
    await this.audit.record({ action: 'LOGOUT', resourceType: 'Session', resourceId: session.id, actorUserId: session.user.id, requestId: context.requestId });
  }

  async ndiInitiate() {
    const proof = await this.ndi.createProofRequest();
    const pollToken = randomBytes(32).toString('base64url');
    const expiresAt = new Date(Date.now() + this.config.get<number>('NDI_LOGIN_TTL_SECONDS', 300) * 1000);
    await this.ndiLogins.save(this.ndiLogins.create({
      threadId: proof.proofRequestThreadId,
      pollTokenHash: this.hash(pollToken),
      status: 'PENDING',
      proofRequestUrl: proof.proofRequestURL,
      deepLinkUrl: proof.deepLinkURL ?? null,
      verifiedIdentity: {}, user: null, expiresAt, completedAt: null, consumedAt: null,
    }));
    return {
      pollToken,
      proofRequestUrl: proof.proofRequestURL,
      deepLinkUrl: proof.deepLinkURL ?? null,
      expiresAt: expiresAt.toISOString(),
    };
  }

  async ndiStatus(pollToken: string, context: RequestContext) {
    const login = await this.ndiLogins.findOneBy({ pollTokenHash: this.hash(pollToken) });
    if (!login) throw new DomainException('NDI_LOGIN_NOT_FOUND', 'This Bhutan NDI login request is no longer available.', 404);
    const expired = await this.expireOverdueNdiLogin(login);
    if (expired) return expired;
    const terminal = this.terminalNdiStatus(login);
    if (terminal) return terminal;
    if (!login.user) throw new DomainException('NDI_ACCOUNT_NOT_LINKED', 'No Dzongjuk account is linked to this verified identity.', 403);
    return this.consumeValidatedNdiLogin(login, login.user, context);
  }

  /** A still-pending request past its TTL is failed out and reported EXPIRED; anything else, this returns null. */
  private async expireOverdueNdiLogin(login: NdiLoginRequestEntity): Promise<{ status: 'EXPIRED' } | null> {
    if (login.status !== 'PENDING' || login.expiresAt > new Date()) return null;
    login.status = 'FAILED';
    login.completedAt = new Date();
    await this.ndiLogins.save(login);
    void this.ndi.unsubscribe(login.threadId);
    return { status: 'EXPIRED' };
  }

  /**
   * The plain `{status}` response for every status that needs no further action, or
   * throws for one already claimed by a prior poll. Null once the request is ready
   * to be consumed (VALIDATED and not yet claimed).
   */
  private terminalNdiStatus(login: NdiLoginRequestEntity): { status: 'PENDING'; expiresAt: string } | { status: 'REJECTED' | 'FAILED' | 'CANCELLED' } | null {
    if (login.status === 'PENDING') return { status: 'PENDING', expiresAt: login.expiresAt.toISOString() };
    if (login.status === 'REJECTED') return { status: 'REJECTED' };
    if (login.status === 'FAILED') return { status: 'FAILED' };
    if (login.status === 'CANCELLED') return { status: 'CANCELLED' };
    if (login.status === 'CONSUMED' || login.consumedAt) {
      throw new DomainException('NDI_LOGIN_CONSUMED', 'This Bhutan NDI login request has already been used.', 409);
    }
    return null;
  }

  /** Atomically claims a validated login (so a concurrent poll cannot double-consume it) and opens the session. */
  private async consumeValidatedNdiLogin(login: NdiLoginRequestEntity, user: UserEntity, context: RequestContext) {
    const claimed = await this.ndiLogins.update(
      { id: login.id, status: 'VALIDATED', consumedAt: IsNull() },
      { status: 'CONSUMED', consumedAt: new Date() },
    );
    if (claimed.affected !== 1) throw new DomainException('NDI_LOGIN_CONSUMED', 'This Bhutan NDI login request has already been used.', 409);
    void this.ndi.unsubscribe(login.threadId);
    const session = await this.createSession(user, 'NDI', context);
    return { status: 'VALIDATED', ...session };
  }

  async ndiCancel(pollToken: string) {
    const login = await this.ndiLogins.findOneBy({ pollTokenHash: this.hash(pollToken) });
    if (!login || login.status !== 'PENDING') return { cancelled: true };
    login.status = 'CANCELLED';
    login.completedAt = new Date();
    await this.ndiLogins.save(login);
    void this.ndi.unsubscribe(login.threadId);
    return { cancelled: true };
  }

  async ndiWebhook(authorization: string | undefined, payload: Record<string, unknown>) {
    this.assertWebhookAuthorization(authorization);
    const threadId = typeof payload.thid === 'string' ? payload.thid : null;
    if (!threadId) throw new DomainException('NDI_WEBHOOK_INVALID', 'The Bhutan NDI webhook is missing thid.', 400);
    const login = await this.ndiLogins.findOneBy({ threadId });
    if (!login || login.status !== 'PENDING') return { accepted: true };

    if (payload.type === 'present-proof/rejected') {
      login.status = 'REJECTED';
      login.completedAt = new Date();
      await this.ndiLogins.save(login);
      return { accepted: true };
    }
    if (payload.type !== 'present-proof/presentation-result' || payload.verification_result !== 'ProofValidated') {
      login.status = 'FAILED';
      login.completedAt = new Date();
      await this.ndiLogins.save(login);
      return { accepted: true };
    }

    const presentation = payload.requested_presentation as Record<string, unknown> | undefined;
    const attributes = presentation?.revealed_attrs as Record<string, unknown> | undefined;
    const cid = this.revealedValue(attributes?.['ID Number']);
    const fullName = this.revealedValue(attributes?.['Full Name']);
    if (!cid || !fullName) {
      login.status = 'FAILED';
      login.completedAt = new Date();
      await this.ndiLogins.save(login);
      return { accepted: true };
    }

    let user = await this.users.findOneBy({ cid });
    if (!user && this.config.get('NDI_ALLOW_TEST_TAKER_PROVISIONING', 'false') === 'true') {
      const role = await this.roles.findOneByOrFail({ code: CanonicalRole.TestTaker, active: true });
      user = await this.users.save(this.users.create({
        email: `ndi-${this.hash(cid).slice(0, 24)}@users.dzongjuk.bt`, cid, fullName, userId: await this.allocateUserId(),
        passwordHash: null, roles: [role], status: 'ACTIVE', ndiLinkedAt: new Date(),
      }));
    }
    if (!user || user.status !== 'ACTIVE') {
      login.status = 'FAILED';
      login.completedAt = new Date();
      login.verifiedIdentity = { cid, fullName };
      await this.ndiLogins.save(login);
      return { accepted: true };
    }

    user.ndiLinkedAt = new Date();
    await this.users.save(user);
    login.user = user;
    login.status = 'VALIDATED';
    login.completedAt = new Date();
    login.verifiedIdentity = {
      cid, fullName,
      relationshipDid: typeof payload.relationship_did === 'string' ? payload.relationship_did : undefined,
    };
    await this.ndiLogins.save(login);
    await this.audit.record({
      action: 'NDI_PROOF_VALIDATED', resourceType: 'User', resourceId: user.id,
      actorUserId: user.id, requestId: `ndi:${threadId}`, safeData: { threadId },
    });
    return { accepted: true };
  }

  private async createSession(user: UserEntity, assurance: 'LOCAL' | 'NDI' | 'MFA', context: RequestContext) {
    const refreshToken = randomBytes(48).toString('base64url');
    const session = await this.sessions.save(this.sessions.create({
      user, assurance, refreshTokenHash: this.hash(refreshToken), lastActivityAt: new Date(),
      expiresAt: new Date(Date.now() + 8 * 60 * 60_000),
      ipHash: context.ip ? this.hash(context.ip) : null, userAgent: context.userAgent?.slice(0, 512) ?? null,
    }));
    await this.audit.record({ action: 'LOGIN_SUCCESS', resourceType: 'Session', resourceId: session.id, actorUserId: user.id, requestId: context.requestId, safeData: { assurance } });
    return { ...this.tokens(session), refreshToken };
  }

  private tokens(session: SessionEntity) {
    const permissions = [...new Set(session.user.roles.flatMap((role) => role.permissions.map((permission) => permission.name)))];
    const claims: AccessClaims = { sub: session.user.id, sessionId: session.id, roles: session.user.roles.map((role) => role.code), permissions, assurance: session.assurance };
    return { accessToken: this.jwt.sign(claims), expiresIn: 900, user: this.publicUser(session.user) };
  }

  private async failedLogin(identifier: string, user: UserEntity | null, context: RequestContext, reason: string): Promise<never> {
    if (user) {
      user.failedLoginCount += 1;
      if (user.failedLoginCount >= 5) {
        user.status = 'LOCKED';
        user.lockedUntil = new Date(Date.now() + this.config.get<number>('LOCKOUT_MINUTES', 30) * 60_000);
      }
      await this.users.save(user);
    }
    await this.logAttempt(identifier, false, context, reason);
    throw new DomainException('INVALID_CREDENTIALS', 'The supplied credentials are invalid.', 401);
  }

  private async logAttempt(identifier: string, success: boolean, context: RequestContext, reason: string | null) {
    await this.attempts.save(this.attempts.create({ identifier, success, reason, ipHash: context.ip ? this.hash(context.ip) : null }));
  }

  private assertWebhookAuthorization(authorization: string | undefined) {
    const expected = this.config.get<string>('NDI_WEBHOOK_BEARER_TOKEN');
    const received = authorization?.replace(/^Bearer\s+/i, '');
    if (!expected || !received) throw new DomainException('NDI_WEBHOOK_UNAUTHORIZED', 'Webhook authentication failed.', HttpStatus.UNAUTHORIZED);
    const left = Buffer.from(expected);
    const right = Buffer.from(received);
    if (left.length !== right.length || !timingSafeEqual(left, right)) {
      throw new DomainException('NDI_WEBHOOK_UNAUTHORIZED', 'Webhook authentication failed.', HttpStatus.UNAUTHORIZED);
    }
  }

  private revealedValue(value: unknown): string | null {
    const first = Array.isArray(value) ? value[0] : value;
    if (!first || typeof first !== 'object') return null;
    const revealed = (first as Record<string, unknown>).value;
    return typeof revealed === 'string' && revealed.trim() ? revealed.trim() : null;
  }


  private hash(value: string) { return createHash('sha256').update(value).digest('hex'); }
  private publicUser(user: UserEntity) {
    return {
      id: user.id, userId: user.userId, email: user.emailSet ? user.email : null,
      emailSet: user.emailSet, passwordSet: user.passwordSet,
      cid: user.cid, fullName: user.fullName, fullNameDz: user.fullNameDz ?? null, dateOfBirth: user.dateOfBirth,
      gender: user.gender, contactNumber: user.contactNumber, phone: user.contactNumber,
      education: user.education, photo: user.photo, avatar: user.photo,
      status: user.status, roles: user.roles.map((role) => role.code),
    };
  }
}

import sharp from 'sharp';
import { DomainException } from '@dzongjuk/common';
export const PASSPORT_PHOTO_MAX_BYTES = 3 * 1024 * 1024;
const invalid = (message: string): never => {
  throw new DomainException('PROFILE_PHOTO_INVALID', message, 400);
};

// Re-encoding decodes the actual image, strips metadata and stores a safe JPEG.
export async function validatePassportPhotoDataUrl(value: string): Promise<string> {
  const match = /^data:(image\/(?:jpeg|png));base64,([A-Za-z0-9+/]+={0,2})$/.exec(value);
  if (!match) return invalid('Please choose a JPG or PNG photo.');
  const bytes = Buffer.from(match[2], 'base64');
  if (!bytes.length || bytes.length > PASSPORT_PHOTO_MAX_BYTES)
    return invalid('This photo could not be saved. Please choose another photo.');
  try {
    const image = sharp(bytes, {
      limitInputPixels: 50_000_000,
      failOn: 'warning',
      animated: false,
    });
    const metadata = await image.metadata();
    if (
      !['jpeg', 'png'].includes(metadata.format ?? '') ||
      `image/${metadata.format}` !== match[1] ||
      (metadata.pages ?? 1) > 1
    )
      return invalid('Please choose a JPG or PNG photo.');
    const width = metadata.autoOrient?.width ?? metadata.width ?? 0;
    const height = metadata.autoOrient?.height ?? metadata.height ?? 0;
    if (width < 350 || height < 450)
      return invalid('The photo is too small. Please upload a higher-quality photo.');
    if (Math.abs(width / height - 7 / 9) > 0.015)
      return invalid('Please adjust your photo in the preview and try saving again.');
    const output = await image
      .autoOrient()
      .resize(350, 450, { fit: 'cover', withoutEnlargement: true })
      .flatten({ background: '#ffffff' })
      .jpeg({ quality: 88, progressive: true })
      .timeout({ seconds: 10 })
      .toBuffer();
    if (output.length > PASSPORT_PHOTO_MAX_BYTES)
      return invalid('This photo could not be saved. Please choose another photo.');
    return `data:image/jpeg;base64,${output.toString('base64')}`;
  } catch (error) {
    if (error instanceof DomainException) throw error;
    return invalid('We could not read this photo. Please choose a different JPG or PNG photo.');
  }
}

import { Injectable } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { DataSource, IsNull, In, Not } from 'typeorm';
import bcrypt from 'bcryptjs';
import { DomainException } from '@dzongjuk/common';
import { TransferUserDto } from './dtos';
import { AuditEventEntity, RoleEntity, SessionEntity, UserEntity, UserHandoverEntity } from './entities';

const singleton = ['admin', 'dcdd', 'exam_head', 'committee_head'];
@Injectable()
export class StaffHandoverService {
 constructor(private readonly db: DataSource, private readonly config: ConfigService) {}
 private services() {
  return [
   ['result', this.config.get<string>('RESULT_SERVICE_URL', 'http://result-service:8004/api/v1')],
   ['assessment', this.config.get<string>('ASSESSMENT_SERVICE_URL', 'http://assessment-content-service:8003/api/v1')],
   ['reporting', this.config.get<string>('REPORTING_SERVICE_URL', 'http://reporting-service:8007/api/v1')],
  ];
 }
 private async call(base: string, path: string, body?: unknown) {
  const secret=this.config.get<string>('INTERNAL_SERVICE_SECRET', '');
  if(secret.length<32) throw new DomainException('HANDOVER_NOT_CONFIGURED','Handover service authentication is not configured.',503);
  try {
   const response=await fetch(base.replace(/\/$/,'')+'/internal/staff-handover'+path, { method:body?'POST':'GET', headers:{'Content-Type':'application/json','x-internal-service-key':secret}, ...(body?{body:JSON.stringify(body)}:{}), signal:AbortSignal.timeout(15000) });
   const envelope=await response.json() as {success:boolean,data:Record<string,number>,error?:{message:string}};
   if(!response.ok || !envelope.success) throw new Error(envelope.error?.message || 'A responsibility service could not complete the handover.');
   return envelope.data;
  } catch(error) { throw new DomainException('HANDOVER_SERVICE_UNAVAILABLE',error instanceof Error?error.message:'Handover service unavailable.',503); }
 }
 async plan(id: string) {
  const source=await this.db.getRepository(UserEntity).findOneBy({id,deletedAt:IsNull()});
  if(!source)throw new DomainException('USER_NOT_FOUND','User not found.',404);
  const pending=await this.db.getRepository(UserHandoverEntity).findOneBy({sourceUserId:id});
  const responsibilities:Record<string,Record<string,number>>={};
  for(const [name,url] of this.services())responsibilities[name]=await this.call(url,'/'+id);
  return {sourceUserId:id,roles:pending?.roleCodes ?? source.roles.filter(r=>r.code!=='test_taker').map(r=>r.code), responsibilities, pending:pending?{targetUserId:pending.targetUserId,targetEmail:pending.targetEmail,status:pending.status,lastError:pending.lastError}:null, preservesHistory:true};
 }
 async transfer(id:string,dto:TransferUserDto,actorId:string,requestId:string) {
  if(id===actorId)throw new DomainException('SELF_DELETE_FORBIDDEN','You cannot delete your own account.');
  if(Boolean(dto.targetUserId)===Boolean(dto.newUser))throw new DomainException('HANDOVER_TARGET_REQUIRED','Choose exactly one existing or new successor.');
  if(dto.targetUserId===id)throw new DomainException('HANDOVER_SELF_TARGET','Choose a different successor.');
  const runner=this.db.createQueryRunner(); await runner.connect();
  const [lock]=await runner.query('SELECT pg_try_advisory_lock(hashtext($1)) AS locked',['staff-handover:'+id]);
  if(!lock.locked){await runner.release();throw new DomainException('HANDOVER_IN_PROGRESS','Another handover attempt is running. Please wait.',409);}
  let job:UserHandoverEntity|undefined;
  try {
   job=await this.db.getRepository(UserHandoverEntity).findOneBy({sourceUserId:id}) ?? undefined;
   if(job && ((dto.targetUserId && dto.targetUserId!==job.targetUserId)||(dto.newUser && dto.newUser.email.toLowerCase()!==job.targetEmail)))throw new DomainException('HANDOVER_TARGET_CONFLICT','Resume with the original successor; responsibilities may already have moved.',409);
   if(job?.status==='COMPLETED')return {deleted:true,transferred:true,targetUserId:job.targetUserId};
   if(!job){
    await this.plan(id); // Every responsibility service must be reachable before freezing the account.
    job=await this.db.transaction('SERIALIZABLE',async m=>{
     const source=await m.findOne(UserEntity,{where:{id,deletedAt:IsNull()},relations:{roles:true}});
     if(!source)throw new DomainException('USER_NOT_FOUND','User not found.',404);
     if(source.handoverPending)throw new DomainException('HANDOVER_IN_PROGRESS','This user is already involved in another handover.',409);
     if(source.roles.length===1 && source.roles[0].code==='test_taker' && !source.requiresRoleTransfer)throw new DomainException('HANDOVER_NOT_REQUIRED','Test Taker-only accounts use ordinary deletion.');
     let target:UserEntity;
     if(dto.newUser){
      if(await m.exists(UserEntity,{where:[{email:dto.newUser.email.toLowerCase()},{cid:dto.newUser.cid}]}))throw new DomainException('USER_DUPLICATE','The successor email or CID already exists.',409);
      const [row]=await m.query('SELECT COALESCE(MAX(NULLIF("userId",\'\')::int),1000)+1 AS next FROM identity.users');
      if(row.next>9999)throw new DomainException('USER_ID_ALLOCATION_FAILED','No available four-digit User ID.',409);
      target=await m.save(UserEntity,m.create(UserEntity,{fullName:dto.newUser.fullName,email:dto.newUser.email.toLowerCase(),cid:dto.newUser.cid,passwordHash:await bcrypt.hash(dto.newUser.password,12),userId:String(row.next),roles:[],status:'DISABLED',requiresRoleTransfer:true}));
     }else{
      const existing=await m.findOne(UserEntity,{where:{id:dto.targetUserId!,deletedAt:IsNull()},relations:{roles:true}});
      if(!existing || existing.status!=='ACTIVE' || existing.handoverPending)throw new DomainException('HANDOVER_TARGET_INVALID','The successor must be an active, unlocked existing user.');
      target=existing;
     }
     target.handoverPending=true;await m.save(UserEntity,target);
     const roleCodes=source.roles.filter(r=>r.code!=='test_taker').map(r=>r.code);
     source.status='DISABLED';source.handoverPending=true;source.requiresRoleTransfer=true;
     await m.save(UserEntity,source);
     await m.update(SessionEntity,{user:{id},revokedAt:IsNull()},{revokedAt:new Date()});
     const created=await m.save(UserHandoverEntity,m.create(UserHandoverEntity,{sourceUserId:id,targetUserId:target.id,targetEmail:target.email,createdTarget:Boolean(dto.newUser),roleCodes,actorUserId:actorId,status:'PENDING',lastError:null}));
     await m.save(AuditEventEntity,m.create(AuditEventEntity,{action:'USER_HANDOVER_STARTED',resourceType:'User',resourceId:id,actorUserId:actorId,requestId,safeData:{transferId:created.id,targetUserId:target.id,roles:roleCodes}}));
     return created;
    });
   }
   for(const [,url] of this.services())await this.call(url,'',{sourceUserId:id,targetUserId:job.targetUserId,transferId:job.id});
   for(const [,url] of this.services()){
    const remaining=await this.call(url,'/'+id);
    if(Object.values(remaining).some(v=>v!==0))throw new DomainException('HANDOVER_INCOMPLETE','Responsibilities remain. Retry the handover.',409);
   }
   const completed=job;
   await this.db.transaction('SERIALIZABLE',async m=>{
    const source=await m.findOneByOrFail(UserEntity,{id});const target=await m.findOne(UserEntity,{where:{id:completed.targetUserId,deletedAt:IsNull()},relations:{roles:true}});
    if(!target || (!completed.createdTarget && target.status!=='ACTIVE'))throw new DomainException('HANDOVER_TARGET_INVALID','The successor is no longer eligible.',409);
    const codes=[...new Set([...target.roles.map(r=>r.code),...completed.roleCodes])];
    const roles=await m.findBy(RoleEntity,{code:In(codes),active:true});if(roles.length!==codes.length)throw new DomainException('ROLE_INVALID','A transferred role is inactive. Restore it before retrying.',409);
    const holders=await m.find(UserEntity,{where:{status:Not('DISABLED'),deletedAt:IsNull()},relations:{roles:true}});
    if(holders.some(u=>u.id!==id&&u.id!==target.id&&u.roles.some(r=>singleton.includes(r.code)&&codes.includes(r.code))))throw new DomainException('ROLE_SINGLETON_CONFLICT','A singleton role now belongs to another active user. Resolve that conflict and retry.',409);
    target.roles=roles;target.status='ACTIVE';target.handoverPending=false;target.requiresRoleTransfer=true;await m.save(UserEntity,target);
    source.roles=[];source.status='DISABLED';source.deletedAt=new Date();source.handoverPending=false;await m.save(UserEntity,source);
    await m.update(SessionEntity,{user:{id:target.id},revokedAt:IsNull()},{revokedAt:new Date()});
    completed.status='COMPLETED';completed.completedAt=new Date();completed.lastError=null;await m.save(UserHandoverEntity,completed);
    await m.save(AuditEventEntity,m.create(AuditEventEntity,{action:'USER_HANDOVER_COMPLETED',resourceType:'User',resourceId:id,actorUserId:actorId,requestId,safeData:{transferId:completed.id,targetUserId:target.id,roles:completed.roleCodes,historyPreserved:true}}));
   });
   return {deleted:true,transferred:true,targetUserId:job.targetUserId};
  } catch(error){
   if(job)await this.db.getRepository(UserHandoverEntity).update(job.id,{lastError:error instanceof Error?error.message:'Handover failed. Retry.'});
   throw error;
  } finally {await runner.query('SELECT pg_advisory_unlock(hashtext($1))',['staff-handover:'+id]);await runner.release();}
 }
