// ─── helpers ─────────────────────────────────────────────────────────────────

const uuid = () => `00000000-0000-4000-8000-${Math.random().toString().slice(2, 14).padEnd(12, '0')}`;

const openExam = (overrides: Partial<ExamEntity> = {}): ExamEntity =>
  Object.assign(new ExamEntity(), {
