    const service = buildService();
    const localActor = mfaActor({ assurance: 'LOCAL' });
    await expect(service.declareResults(uuid(), localActor, 'req-1'))
      .rejects.toMatchObject({ response: { code: 'PRIVILEGED_ASSURANCE_REQUIRED' } });
